// 交互式关系创建示例
function setupRelationEditor(svg, graph) {
  // 允许拖拽创建关系
  let dragLine = svg.append('path')
      .attr('class', 'link dragline hidden')
      .attr('d', 'M0,0L0,0');

  // 节点拖拽开始
  function dragstart(d) {
    if (!d3.event.active) simulation.alphaTarget(0.3).restart();
    dragLine
        .classed('hidden', false)
        .attr('d', `M${d.x},${d.y}L${d.x},${d.y}`);
    d.fixed = true;
  }

  // 拖拽中更新线条
  function drag(d) {
    dragLine.attr('d', `M${d.x},${d.y}L${d3.event.x},${d3.event.y}`);
  }

  // 拖拽结束，创建关系
  function dragend(d) {
    // 检查是否拖到了另一个节点
    let targetNode = simulation.find(d3.event.x, d3.event.y, 10);
    if (targetNode && targetNode !== d) {
      // 打开关系类型选择对话框
      openRelationTypeDialog(d, targetNode, (relationType) => {
